// This is a real routed LAN, not traffic generated by the gateway itself:
// client namespace -- lan0 -- KONE -- wan0 -- upstream namespace.
// Proxy and DNS addresses have only a physical default route before capture;
// the /1 TUN routes would recapture them without physical-interface binding.
func TestSystemGatewayLANFullCapture(t *testing.T) {
	cfg := systemConfig(t)
	clientNS := fmt.Sprintf("kone-client-%d", os.Getpid())
	wanNS := fmt.Sprintf("kone-wan-%d", os.Getpid())
	for _, name := range []string{clientNS, wanNS} {
		systemCommand(t, "netns", "add", name)
		t.Cleanup(func() { systemCommand(t, "netns", "del", name) })
	}
	for _, pair := range []struct{ name, peer, ns, local, remote string }{
		{"lan0", "client0", clientNS, "192.0.2.1/24", "192.0.2.2/24"},
		{"wan0", "server0", wanNS, "198.18.0.1/24", "198.18.0.2/24"},
	} {
		systemCommand(t, "link", "add", pair.name, "type", "veth", "peer", "name", pair.peer)
		t.Cleanup(func() { systemCommand(t, "link", "del", pair.name) })
		systemCommand(t, "link", "set", pair.peer, "netns", pair.ns)
		systemCommand(t, "addr", "add", pair.local, "dev", pair.name)
		systemCommand(t, "link", "set", pair.name, "up")
		systemCommand(t, "-n", pair.ns, "link", "set", "lo", "up")
		systemCommand(t, "-n", pair.ns, "addr", "add", pair.remote, "dev", pair.peer)
		systemCommand(t, "-n", pair.ns, "link", "set", pair.peer, "up")
	}
	systemCommand(t, "-n", clientNS, "route", "add", "default", "via", "192.0.2.1")
	systemCommand(t, "route", "add", "default", "via", "198.18.0.2", "dev", "wan0")
	t.Cleanup(func() { systemCommand(t, "route", "del", "default", "via", "198.18.0.2", "dev", "wan0") })
	for _, addr := range []string{"203.0.113.2/32", "203.0.113.53/32", "203.0.113.9/32"} {
		systemCommand(t, "-n", wanNS, "addr", "add", addr, "dev", "lo")
	}
	for path, value := range map[string]string{"/proc/sys/net/ipv4/ip_forward": "1", "/proc/sys/net/ipv4/conf/all/rp_filter": "0", "/proc/sys/net/ipv4/conf/lan0/rp_filter": "0", "/proc/sys/net/ipv4/conf/wan0/rp_filter": "0"} {
		if err := os.WriteFile(path, []byte(value), 0600); err != nil {
			t.Fatal(err)
		}
	}
	executable, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 60*time.Second)
	defer cancel()
	server := exec.CommandContext(ctx, "ip", "netns", "exec", wanNS, executable, "-test.run=^TestGatewayNamespaceHelper$", "-test.timeout=55s")
	server.Env = append(os.Environ(), "KONE_GATEWAY_ROLE=upstream")
	var logs bytes.Buffer
	server.Stderr = &logs
	output, err := server.StdoutPipe()
	if err != nil {
		t.Fatal(err)
	}
	if err = server.Start(); err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { server.Process.Kill(); server.Wait() })
	ready := make(chan string, 1)
	go func() { line, _ := bufio.NewReader(output).ReadString('\n'); ready <- line }()
	var proxyPort, dnsPort, udpPort, directPort int
	select {
	case line := <-ready:
		if _, err = fmt.Sscanf(line, "%d %d %d %d", &proxyPort, &dnsPort, &udpPort, &directPort); err != nil {
			t.Fatalf("upstream startup: %q: %v", line, err)
		}
	case <-ctx.Done():
		t.Fatal("upstream startup timed out")
	}
	cfg.Core.AutoRoute = true
	cfg.Core.OutboundInterface = "wan0"
	cfg.DNS.Servers = []string{fmt.Sprintf("203.0.113.53:%d", dnsPort)}
	cfg.Outbounds = append(cfg.Outbounds, kone.OutboundConfig{Name: "Gateway", Type: kone.OutboundProxy, URL: fmt.Sprintf("http://203.0.113.2:%d", proxyPort)})
	cfg.Rule = []kone.RuleConfig{{Schema: "IP-CIDR", Pattern: "203.0.113.9/32", Outbound: kone.BuiltinDirect}, {Schema: "IP-CIDR", Pattern: "198.51.100.0/24", Outbound: kone.BuiltinReject}, {Schema: "FINAL", Outbound: "Gateway"}}
	_, stop, done := systemStart(t, cfg)
	client := exec.CommandContext(ctx, "ip", "netns", "exec", clientNS, executable, "-test.run=^TestGatewayNamespaceHelper$", "-test.timeout=20s")
	client.Env = append(os.Environ(), "KONE_GATEWAY_ROLE=client", fmt.Sprintf("KONE_GATEWAY_DNS=10.203.0.1:%d", cfg.DNS.ListenPort), fmt.Sprintf("KONE_GATEWAY_UDP_PORT=%d", udpPort), fmt.Sprintf("KONE_GATEWAY_DIRECT_PORT=%d", directPort))
	if out, err := client.CombinedOutput(); err != nil {
		t.Fatalf("LAN forwarding: %v\n%s", err, out)
	}
	// Management must retain the LAN client's identity, rather than loopback or
	// the TUN listener's rewritten source address.
	response, err := http.Get("http://" + cfg.General.ManagerAddr + "/host/")
	if err != nil {
		t.Fatal(err)
	}
	data, err := io.ReadAll(response.Body)
	response.Body.Close()
	if err != nil || !strings.Contains(string(data), "192.0.2.2") {
		t.Fatalf("LAN source not retained: %v %s", err, data)
	}
	stop()
	if err := systemWait(t, done); err != nil {
		t.Fatal(err)
	}
	noSystemInterface(t, cfg)
	if routes := systemCommand(t, "route", "show", "0.0.0.0/1"); routes != "" {
		t.Fatalf("capture route leaked: %s", routes)
	}
	if routes := systemCommand(t, "route", "show", "128.0.0.0/1"); routes != "" {
		t.Fatalf("capture route leaked: %s", routes)
	}
	if routes := systemCommand(t, "route", "show", "default"); !strings.Contains(routes, "198.18.0.2") {
		t.Fatalf("physical default route lost: %s", routes)
	}
}

func TestGatewayNamespaceHelper(t *testing.T) {
	switch os.Getenv("KONE_GATEWAY_ROLE") {
	case "upstream":
		gatewayUpstream(t)
	case "client":
		gatewayClient(t)
	default:
		t.Skip("namespace helper")
	}
}

func gatewayUpstream(t *testing.T) {
	web, err := net.Listen("tcp4", "203.0.113.9:0")
	if err != nil {
		t.Fatal(err)
	}
	go http.Serve(web, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) { fmt.Fprint(w, "gateway-upstream") }))
	proxy, err := net.Listen("tcp4", "203.0.113.2:0")
	if err != nil {
		t.Fatal(err)
	}
	go http.Serve(proxy, http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != "CONNECT" {
			http.Error(w, "CONNECT required", 400)
			return
		}
		remote, err := net.Dial("tcp4", web.Addr().String())
		if err != nil {
			http.Error(w, err.Error(), 502)
			return
		}
		defer remote.Close()
		client, buffer, err := w.(http.Hijacker).Hijack()
		if err != nil {
			return
		}
		defer client.Close()
		buffer.WriteString("HTTP/1.1 200 Connection established\r\n\r\n")
		buffer.Flush()
		done := make(chan struct{})
		go func() { io.Copy(remote, buffer); remote.Close(); close(done) }()
		io.Copy(client, remote)
		client.Close()
		<-done
	}))
	dnsConn, err := net.ListenPacket("udp4", "203.0.113.53:0")
	if err != nil {
		t.Fatal(err)
	}
	dnsServer := &dns.Server{PacketConn: dnsConn, Handler: dns.HandlerFunc(func(w dns.ResponseWriter, r *dns.Msg) {
		reply := new(dns.Msg)
		reply.SetReply(r)
		if len(r.Question) == 1 && r.Question[0].Qtype == dns.TypeA {
			reply.Answer = []dns.RR{&dns.A{Hdr: dns.RR_Header{Name: r.Question[0].Name, Rrtype: dns.TypeA, Class: dns.ClassINET, Ttl: 60}, A: net.IPv4(203, 0, 113, 9)}}
		}
		w.WriteMsg(reply)
	})}
	go dnsServer.ActivateAndServe()
	udp, err := net.ListenPacket("udp4", "203.0.113.9:0")
	if err != nil {
		t.Fatal(err)
	}
	go func() {
		data := make([]byte, 65535)
		for {
			n, addr, err := udp.ReadFrom(data)
			if err != nil {
				return
			}
			udp.WriteTo(data[:n], addr)
		}
	}()
	fmt.Printf("%d %d %d %d\n", proxy.Addr().(*net.TCPAddr).Port, dnsConn.LocalAddr().(*net.UDPAddr).Port, udp.LocalAddr().(*net.UDPAddr).Port, web.Addr().(*net.TCPAddr).Port)
	select {}
}

func gatewayClient(t *testing.T) {
	query := new(dns.Msg)
	query.SetQuestion("gateway.example.", dns.TypeA)
	answer, _, err := (&dns.Client{Timeout: 3 * time.Second}).Exchange(query, os.Getenv("KONE_GATEWAY_DNS"))
	if err != nil || len(answer.Answer) != 1 {
		t.Fatalf("LAN DNS: %v %v", err, answer)
	}
	fake := answer.Answer[0].(*dns.A).A.String()
	if !strings.HasPrefix(fake, "10.203.0.") {
		t.Fatalf("not a Fake-IP: %s", fake)
	}
	client := &http.Client{Transport: &http.Transport{DisableKeepAlives: true}, Timeout: 3 * time.Second}
	for _, target := range []string{fake, "203.0.113.99", "203.0.113.9:" + os.Getenv("KONE_GATEWAY_DIRECT_PORT")} {
		response, err := client.Get("http://" + target + "/")
		if err != nil {
			t.Fatal(err)
		}
		body, err := io.ReadAll(response.Body)
		response.Body.Close()
		if err != nil || string(body) != "gateway-upstream" {
			t.Fatalf("LAN HTTP: %q %v", body, err)
		}
	}
	if response, err := client.Get("http://198.51.100.99/"); err == nil {
		response.Body.Close()
		t.Fatal("REJECT policy allowed LAN HTTP")
	}
	port, err := strconv.Atoi(os.Getenv("KONE_GATEWAY_UDP_PORT"))
	if err != nil {
		t.Fatal(err)
	}
	for _, target := range []string{fake, "203.0.113.9"} {
		conn, err := net.DialUDP("udp4", nil, &net.UDPAddr{IP: net.ParseIP(target), Port: port})
		if err != nil {
			t.Fatal(err)
		}
		conn.SetDeadline(time.Now().Add(3 * time.Second))
		_, err = conn.Write([]byte("LAN UDP"))
		if err != nil {
			t.Fatal(err)
		}
		data := make([]byte, 32)
		n, err := conn.Read(data)
		conn.Close()
		if err != nil || string(data[:n]) != "LAN UDP" {
			t.Fatalf("LAN UDP: %q %v", data[:n], err)
		}
	}
}
